"""Hand-reviewed anatomy in native roster-crop coordinates. No game code."""


def body(name, top, bottom, pivot, parent, z):
    return dict(name=name, top=top, bottom=bottom, pivot=pivot, parent=parent, z=z)


def chain(name, points, polygon, parent, names=None, group='limb', z=10):
    return dict(name=name, points=points, polygon=polygon, parent=parent,
                names=names or ['coxa', 'femur', 'claw'], group=group, z=z)


def extra(name, polygon, pivot, parent, z, group='body', **kw):
    return dict(name=name, polygon=polygon, pivot=pivot, parent=parent, z=z, group=group, **kw)


def tail(points, polygon, parent, count):
    return dict(points=points, polygon=polygon, parent=parent, count=count)


